\begin{align*}
\text{Area of } \triangle T_1 T_2 T_3 &= \frac{1}{2}\cdot |T_1 O|\cdot |T_2 O| \\
&= \frac{1}{2}\cdot \left(\frac{\sqrt{2}}{2}\right)\cdot \left(\frac{\sqrt{2}}{2}\right) \\
&= \boxed{\frac{1}{4}}
\end{align*}

